EXTRAS = [
dict(n=41, gr='likeing', vb='play,paint,hike,read,cook',
 c1="Hobbies pelo mundo|Os ingleses amam 'gardening' (jardinagem) e 'birdwatching' (observar pássaros). Os americanos curtem 'camping' e 'barbecue'. Em inglês, 'to take up a hobby' é começar um passatempo.",
 c2="Play, go e do|Para esportes de bola use play (play tennis); para atividades terminadas em -ing use go (go swimming); para atividades sem bola nem -ing use do (do yoga). Regra prática para nunca errar.",
 ar=("Weekend hobbies","On Maple Street everybody has a hobby. Kai plays the guitar and goes surfing at the weekend. Lara paints big colorful pictures and does yoga every morning. Ben grows tomatoes in his garden and cooks fresh sauce. Mia reads three books a month. On Saturdays the neighbors meet in the plaza and show their hobbies. Kai plays a song, Lara shows a painting and Ben shares his tomatoes. \"Hobbies make life richer,\" says Mia. Everybody agrees.","Cada vizinho tem um passatempo e os divide aos sábados.","O que Ben faz?=Grows tomatoes|Plays guitar|Paints;;Quantos livros Mia lê por mês?=Three|One|Ten"),
 ex="It's my cup of tea.=É a minha praia.~Gosto|I'm hooked on it.=Estou viciado nisso.~Paixão|I do it for fun.=Faço por diversão.~Hobby|Let's give it a try.=Vamos tentar.~Convite|It keeps me busy.=Me mantém ocupado.~Hobby",
 tf="Play the guitar é tocar violão.=T|Do yoga está correto.=T|Go swimming é nadar.=T|Ben pinta quadros.=F",
 odd="guitar,piano,chess,yoga=yoga|play,go,do,table=table"),
dict(n=42, gr='ps3', vb='win,play,run,score,cheer',
 c1="Torcida em inglês|'Go, team!' e 'Let's go!' são gritos de torcida. O estádio é 'stadium', a partida é 'match' (UK) ou 'game' (EUA), e o placar se lê 'two to one'. 'Draw' ou 'tie' é empate.",
 c2="Esportes americanos|Os EUA têm 'baseball', 'basketball' e 'American football' como esportes nacionais. No Super Bowl, mais de 100 milhões de pessoas assistem ao jogo final. O intervalo tem shows famosos.",
 ar=("Match day","Saturday is match day. The stadium is full of people with scarves and flags. Beto plays in the first half. He runs fast and passes the ball to Jonas. Ruth cheers loudly from the stands. Jonas scores a goal! At half time the score is two to two. In the second half, the home team wins three to two. The crowd sings and dances. After the match, the players shake hands with the other team. \"Good game!\" they say. Sport teaches respect.","Dia de jogo: o time da casa vira e vence por 3 a 2.","Qual é o placar final?=3 to 2|2 to 2|1 to 0;;Quem comemora na arquibancada?=Ruth|Beto|Jonas"),
 ex="Good game!=Bom jogo!~Fair play|It's a tie.=É empate.~Placar|We won by a landslide.=Ganhamos de lavada.~Vitória|The ball is in your court.=A bola está com você.~Idiom|Go for it!=Vá em frente!~Incentivo",
 tf="Two to one é 2 a 1.=T|Match e game podem ser partida.=T|O placar final foi 2 a 2.=F|Ruth joga futebol no campo.=F",
 odd="soccer,tennis,swimming,stadium=stadium|win,lose,score,chair=chair"),
dict(n=43, gr='polite2', vb='invite,accept,join,meet,bring',
 c1="Convites em inglês|'RSVP' vem do francês e significa 'responda, por favor'. Convidados dizem 'I'd love to!' quando aceitam e 'Sorry, I can't make it' quando não podem ir.",
 c2="Piquenique|Em países de língua inglesa o piquenique é tradição: sanduíches, frutas e muita limonada. Em Londres, parques como Hyde Park ficam cheios nos dias de sol. 'Picnic basket' é a cesta de piquenique.",
 ar=("The picnic plan","Yuki invites her friends to a picnic in the park. Kofi says yes right away. Ana says no because she has to work. Pog says maybe. On Saturday at two o'clock, the park is full of sun. Yuki brings rice balls, Kofi brings sandwiches and Pog brings juice. They sit on a blanket under a big tree. At four, Ana arrives: her boss let her go early! Everyone shouts, \"Surprise!\" She sits down, eats a sandwich and smiles. \"Best Saturday ever,\" she says.","Yuki organiza um piquenique; mesmo quem disse não acaba chegando.","Quem diz não no começo?=Ana|Kofi|Pog;;Quem traz suco?=Pog|Yuki|Kofi"),
 ex="I'd love to!=Adoraria!~Aceitar|Sorry, I can't make it.=Desculpe, não consigo ir.~Recusar|Count me in!=Pode contar comigo!~Aceitar|Maybe next time.=Talvez na próxima.~Recusar|It's on me.=É por minha conta.~Convite",
 tf="I'd love to aceita um convite.=T|Sorry, I can't recusa um convite.=T|O piquenique é no sábado.=T|Pog traz sanduíches.=F",
 odd="picnic,party,concert,sandwich=sandwich|invite,accept,decline,tree=tree"),
dict(n=44, gr='goingto', vb='travel,visit,stay,pack,book',
 c1="Gonna: a forma da fala|Na fala, 'going to' vira 'gonna': 'I'm gonna travel'. É muito comum em músicas e séries, mas na escrita formal use 'going to'.",
 c2="Viagens com planos|Em inglês, 'itinerary' é o roteiro de viagem, 'to pack' é fazer a mala e 'to book' é reservar. 'Bucket list' é a lista de coisas para fazer antes de morrer.",
 ar=("A weekend in the mountains","Sven is going to hike in the mountains this weekend. He is going to leave on Friday evening and stay in a small hotel. On Saturday he is going to walk for six hours and take many photos. Pia is going to join him on Sunday. They are going to eat at a mountain cafe and relax in a spa. On Monday Sven is going to go back to work, tired but very happy. \"Weekends like this give me energy,\" he says.","Sven programa um fim de semana de trilha e relaxamento.","Quando Sven vai sair?=Friday evening|Saturday|Monday;;O que farão no domingo?=Relax in a spa|Walk six hours|Work"),
 ex="I'm planning to...=Estou planejando...~Plano|I'm looking forward to it.=Estou ansioso.~Expectativa|Fingers crossed!=Dedos cruzados!~Torcer|It's all set.=Está tudo certo.~Confirmar|Bon voyage!=Boa viagem!~Despedida",
 tf="I'm going to travel é um plano.=T|Gonna significa going to.=T|Sven vai de avião.=F|Sven vai ficar em um hotel.=T",
 odd="hike,travel,swim,hotel=hotel|going to,gonna,will,table=table"),
dict(n=45, gr='poss', vb='celebrate,give,sing,blow,open',
 c1="Happy Birthday|A música 'Happy Birthday to You' é uma das mais cantadas do mundo e é tradição em países de língua inglesa. Depois, a pessoa faz um pedido e sopra as velas. 'Make a wish!' é o que todos gritam.",
 c2="Festas pelo mundo|No Reino Unido, comemora-se a 'Bonfire Night' (5 de novembro). Nos EUA, o 'Thanksgiving' e o 'Halloween' são os mais populares. Em todos, família e comida são protagonistas.",
 ar=("Tina's surprise","Tina is thirty today. She thinks everybody forgot her birthday. But Pete and the neighbors are in the plaza with balloons, a big chocolate cake and a banner: HAPPY BIRTHDAY! When Tina arrives, everybody shouts, \"Surprise!\" She laughs and almost cries. Mia hands her a gift. Pete sings 'Happy Birthday' with his loud voice. Tina makes a wish and blows out the candles. She says, \"This is the best birthday ever. Thank you, my friends!\"","Os vizinhos preparam uma festa surpresa para os 30 anos de Tina.","Quantos anos Tina faz?=Thirty|Twenty|Forty;;Qual é o sabor do bolo?=Chocolate|Vanilla|Carrot"),
 ex="Many happy returns!=Muitos anos de vida!~Britânico|Make a wish!=Faça um pedido!~Aniversário|Congratulations!=Parabéns!~Conquista|Cheers!=Saúde!~Brinde|It's the thought that counts.=O que vale é a intenção.~Presente",
 tf="Make a wish é faça um pedido.=T|Tina tem vinte anos.=F|Surprise party é uma festa surpresa.=T|Pete traz um bolo de cenoura.=F",
 odd="cake,balloon,gift,hammer=hammer|happy,birthday,party,Tuesday=Tuesday"),
dict(n=46, gr='wh', vb='talk,meet,ask,listen,laugh',
 c1="Small talk é uma arte|Falar sobre clima, viagens e comida é a forma mais comum de começar conversas em inglês. Evite política e dinheiro com desconhecidos. Perguntas abertas (What, How) mantêm a conversa.",
 c2="Question tags|Em inglês, as 'question tags' são perguntas curtas no fim: 'Nice party, isn't it?' / 'You're from Brazil, aren't you?' Elas convidam o outro a concordar e mantêm a conversa viva.",
 ar=("A party on the roof","Will goes to a party on a rooftop. He doesn't know many people, so he talks to Lena. \"Nice party, isn't it?\" he says. \"Yes, the music is great!\" she answers. They talk about music, work and travel. Lena is a pilot and has been to forty countries. Will is a teacher and loves old movies. At the end of the night, they exchange phone numbers and promise to have coffee next week. Will walks home happy: a simple \"Nice party, isn't it?\" started a new friendship.","Will conhece a piloto Lena em uma festa e trocam telefones.","Onde é a festa?=On a rooftop|At a school|At the airport;;Qual é a profissão de Lena?=Pilot|Doctor|Chef"),
 ex="How do you know the host?=Como você conhece o anfitrião?~Festa|What brings you here?=O que o traz aqui?~Abrir conversa|Nice talking to you.=Foi bom conversar.~Despedida|Let's catch up soon.=Vamos nos ver em breve.~Despedida|Small world!=Mundo pequeno!~Coincidência",
 tf="Small talk é uma conversa leve.=T|Nice party, isn't it? é uma question tag.=T|Lena é professora.=F|Will é professor.=T",
 odd="music,party,talk,spoon=spoon|nice,great,lovely,but=but"),
dict(n=47, gr='adj', vb='have,wear,look,smile,wave',
 c1="Descrever sem ofender|Em inglês, prefira 'slim' (magro/esbelto) a 'skinny' (muito magro) e 'curvy' a 'fat'. 'Tall', 'short' e 'medium height' são neutros. Descreva o cabelo, os olhos e a roupa.",
 c2="Retratos falados|A polícia usa retratos falados baseados em descrições: 'He's tall, has short brown hair and green eyes.' Treinar essas frases ajuda a descrever pessoas em qualquer situação.",
 ar=("Lost and found","At the market, Mina cannot find her son. She runs to the security guard, Hiro, and describes the boy: \"He's about ten years old. He's short and has curly hair. He's wearing a red jacket and glasses.\" Hiro calls his team on the radio. Five minutes later, a girl finds the boy in the toy shop. He is fine, just looking at robots. Mina hugs him and says, \"Never go away without telling me!\" The boy smiles. \"Sorry, Mom! Look at this robot!\"","Mina descreve o filho perdido e ele é achado na loja de brinquedos.","O que o menino usa?=A red jacket|A blue hat|A green coat;;Onde o encontram?=In the toy shop|At school|At home"),
 ex="He takes after his father.=Ele puxou o pai.~Família|She's a bit shy.=Ela é um pouco tímida.~Personalidade|He has a good sense of humor.=Ele tem bom humor.~Elogio|She's tall, dark and handsome.=Alto, moreno e bonito.~Expressão|I'd recognize you anywhere!=Eu te reconheceria em qualquer lugar!~Reencontro",
 tf="Curly hair é cabelo cacheado.=T|The boy wears a green coat.=F|Hiro é o segurança.=T|Mina perde a filha.=F",
 odd="tall,short,young,table=table|hair,eyes,glasses,Monday=Monday"),
dict(n=48, gr='there', vb='live,love,visit,walk,enjoy',
 c1="City ou town?|'City' é uma cidade grande; 'town' é uma cidade pequena; 'village' é uma vila. 'Downtown' (EUA) ou 'city centre' (UK) é o centro. 'Suburb' é o subúrbio.",
 c2="Cidades vivas|Cidades como Londres e Nova York têm mais de 8 milhões de habitantes. Já 'Maple Street' é um pequeno universo. Em inglês, 'a big city' e 'a small town' são tema de muitas conversas.",
 ar=("Two cities","Ida lives in a big city with tall buildings, wide streets and many parks. There are three huge museums and a famous river. It is busy and noisy, but it is full of life. Diego lives on Maple Street, a small street with trees, a bakery and a plaza. It is quiet and peaceful, and everybody knows each other. Ida says, \"I love the energy of my city.\" Diego says, \"I love the calm of my street.\" Both are happy. A home is a place where you feel good.","Uma cidade grande e uma rua pequena, cada uma com seu charme.","O que a cidade de Ida tem?=Many parks and museums|A beach|Mountains;;Como é a rua de Diego?=Quiet|Dangerous|Dirty"),
 ex="It's the heart of the city.=É o coração da cidade.~Centro|It's off the beaten track.=Fica fora do roteiro comum.~Lugar tranquilo|The city never sleeps.=A cidade nunca dorme.~Nova York|It's a hidden gem.=É uma joia escondida.~Lugar especial|Put it on the map.=Colocar no mapa.~Fama",
 tf="There are three parks na cidade de Ida.=T|Diego vive em uma cidade grande.=F|Maple Street é quieta.=T|Em Maple Street ninguém se conhece.=F",
 odd="park,museum,river,spoon=spoon|big,small,quiet,table=table"),
dict(n=49, gr='polite2', vb='borrow,lend,help,thank,water',
 c1="Vizinhos amigáveis|Em países de língua inglesa, é comum levar uma torta ou um bolo aos novos vizinhos: 'welcome basket'. Em troca, os vizinhos oferecem ajuda e dicas locais.",
 c2="Could ou can?|'Could you help me?' é mais educado que 'Can you help me?'. Para pedir emprestado, use 'Could I borrow…?'. Em inglês, ser cortês é mais importante do que ser direto.",
 ar=("Good neighbors","On Maple Street neighbors help each other. Colin borrows a ladder from Naomi to fix a lamp. Naomi waters Colin's plants when he is on vacation. Mia brings bread on Sundays. When it snows, everybody cleans the sidewalks together. One day an old woman, Mrs. Brown, loses her key. All the neighbors look for it and find it under a flowerpot. \"A street is a family,\" says Colin. Mrs. Brown cries with joy and bakes a pie for everyone.","Os vizinhos da Maple Street se ajudam sempre.","O que Colin pede a Naomi?=A ladder|A cake|A book;;Onde acham a chave?=Under a flowerpot|In a bag|On the table"),
 ex="Could you give me a hand?=Poderia me dar uma mão?~Pedir ajuda|I owe you one.=Eu te devo uma.~Agradecer|No worries.=Sem problema.~Informal|Thanks a bunch!=Muito obrigado!~Informal|Mind if I borrow it?=Posso pegar emprestado?~Pedido",
 tf="Could you…? é mais educado que Can you…?=T|Colin é a vizinha.=F|Mrs. Brown perdeu a chave.=T|Os vizinhos dizem no.=F",
 odd="ladder,key,flowerpot,sofa=sofa|borrow,lend,help,sleep=sleep"),
dict(n=50, gr='goingto', vb='invite,play,paint,cook,meet',
 c1="Clubes de bairro|Em países de língua inglesa há clubes para tudo: 'book club', 'chess club', 'running club'. É a melhor maneira de conhecer pessoas e praticar inglês com assuntos que você gosta.",
 c2="Grupos e comunidade|Em inglês, 'to join a club' é entrar em um clube, 'member' é o membro e 'meeting' é o encontro. Muitos clubes são gratuitos e abertos a iniciantes.",
 ar=("The Saturday club","Every Saturday afternoon, the neighbors meet in the plaza. Kai plays the guitar. Lara paints a picture of the sunset. Ben brings fresh tomatoes and Mia reads a story aloud. Children run around and play hide-and-seek. When the sun goes down, they all share the food: bread, tomatoes and cake. Mia says, \"Next Saturday we are going to do it again.\" Everyone answers, \"Of course! See you next Saturday!\" It is simple, but it makes the week special.","O clube de sábado junta vizinhos com música, pintura e comida.","Quem lê em voz alta?=Mia|Kai|Ben;;Quando se encontram?=Every Saturday|Every Monday|Once a year"),
 ex="Join the club!=Entre para o clube!~Convite|Let's get together.=Vamos nos reunir.~Encontro|Count me in.=Pode contar comigo.~Participar|Sounds like fun.=Parece divertido.~Resposta|See you around.=A gente se vê.~Despedida",
 tf="O clube se reúne aos sábados.=T|Kai pinta.=F|Mia lê em voz alta.=T|Ben traz bolo.=F",
 odd="guitar,painting,tomatoes,Monday=Monday|club,meeting,member,lamp=lamp"),
]
